function randomChoice(list) {
    return list[Math.floor(Math.random() * list.length)];
}

function getCard(title) {
  for (const card of storyCards) {
    if (card.title === title) return card;
  }
  return null;
}

function buildCard(template) {
  addStoryCard("%@%");
  const card = getCard("%@%");
  if (card) {
    card.title = template.title;
    card.entry = template.entry;
    card.description = template.description;
    card.type = template.type;
    card.keys = template.keys;
  }
}

function eraseCard(card) {
  card.title = "%@%";
  for (const [i, c] of storyCards.entries()) {
    if (c.title === "%@%") {
      removeStoryCard(i);
      break;
    }
  }
}

function rollAndInjectOnceAtStart() {
    if (!state.hasRolled) {
        var entries = [
            { title: "Mysterious Stranger", entry: "A cloaked figure watches you from the shadows." },
            { title: "Lost Relic", entry: "An ancient relic is rumored to lie beneath the ruins." },
            { title: "Whispering Woods", entry: "The trees here seem to whisper secrets to one another." }
        ];
        var selection = randomChoice(entries);
        addStoryCard(["."], selection.entry, "default");
        state.hasRolled = true;
        state.message = `Lore injected: ${selection.title}`;
    }
}

