function replaceGiftPlaceholder(giftName) {
  if (text.includes("%Gift")) {
    text = text.replace("%Gift", "[SYSTEM] Your starting gift: ✨ " + giftName);
  }
}

function rollNewGift() {
  let rolledGift, name, desc;
  do {
    rolledGift = giftList[Math.floor(Math.random() * giftList.length)];
    const parts = rolledGift.split(" - ");
    name = parts[0]?.trim();
    desc = parts[1]?.trim();
  } while (!name || !desc || name === state.giftName);

  state.giftName = name;
  state.giftDescription = desc;

  // Remove previous gift card
  const oldGift = storyCards.find(c => c.title.startsWith("Gift:"));
  if (oldGift) eraseCard(oldGift);

  // Create new gift card
  buildCard({
    title: "Gift: " + state.giftName,
    entry: `{The moment you appear in the Isekai world you are granted a gift: ${state.giftDescription} You did not have any powers of gifts before coming to the Isekai world. }`,
    description: "",
    type: "Story Card",
    keys: "you"
  });
}

// Initial gift logic
function getRandomGift() {
  if (!state.giftCardBuilt) {
    rollNewGift();
    replaceGiftPlaceholder(state.giftName);
    state.giftCardBuilt = true;
  }
}

// Gift reroll handler
function handleGiftReroll() {
  rollNewGift();
  state._giftRerolled = true;
  state._giftMessage = `🎁 The gift reshapes itself... You now receive: **${state.giftName}**`;
}

function getRandomOpeningLocation(text) {
  const key = `${transportationType}|${worldType}`;
  const possibleLocations = locationPool[key];

  if (!possibleLocations || !possibleLocations.length) {
    return text; // No crashing, no console, just safely return
  }

  const chosenLocation = possibleLocations[Math.floor(Math.random() * possibleLocations.length)];

  if (typeof text !== 'undefined') {
    if (text.includes("%Location")) {
      const locationText = chosenLocation.openingText;
      text = text.replace("%Location", locationText);
    }

    if (text.includes("%LocText")) {
      const locationText1 = chosenLocation.title;
      text = text.replace("%LocText", "[SYSTEM] Opening rolled: " + locationText1);
    }
  } // <<-- this closing bracket was missing!

  buildCard({
    title: "Starting Circumstances: " + chosenLocation.title,
    entry: "{You find yourself in an Isekai world, the way you appear inside it is: " + transportationType + ". The circumstances of your summoning end up as follows: " + chosenLocation.entry + " }", // (objective, factual description)
    description: "",
    type: "Story Card",
    keys: "you"
  });

  openingLocation = chosenLocation.title;

  return text; // important: return the modified text
}




